const body = $json.body || $json;
return { json: {
  name: (body.name || body.full_name || '').trim(),
  email: (body.email || '').trim(),
  phone: (body.phone || '').trim(),
  practice_area: (body.practice_area || body.matter_type || '').trim(),
  case_description: (body.case_description || body.message || body.details || '').trim(),
  submitted_at: new Date().toISOString(),
} };

// Rule-based eligibility routing -- no AI judgment of case merits, just matching against the
// firm's own configured practice areas and keyword lists. Every submission gets a tier; nothing
// is silently dropped.
const lead = $json;
const firmPracticeAreas = ($vars.FIRM_PRACTICE_AREAS || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const urgentKeywords = ($vars.URGENT_KEYWORDS || 'arrested,court date,eviction notice,restraining order,emergency').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const disqualifyingKeywords = ($vars.DISQUALIFYING_KEYWORDS || 'already have a lawyer,already retained,just researching,student project').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);

const descLower = lead.case_description.toLowerCase();
const practiceAreaLower = lead.practice_area.toLowerCase();

const practiceAreaMatch = firmPracticeAreas.length === 0 || firmPracticeAreas.some(pa => practiceAreaLower.includes(pa) || pa.includes(practiceAreaLower));
const hasUrgentSignal = urgentKeywords.some(k => descLower.includes(k));
const hasDisqualifyingSignal = disqualifyingKeywords.some(k => descLower.includes(k));

let fitScore = 50;
if (practiceAreaMatch) fitScore += 30;
if (hasUrgentSignal) fitScore += 20;
if (hasDisqualifyingSignal) fitScore -= 50;
fitScore = Math.max(0, Math.min(100, fitScore));

let routingTier;
if (hasDisqualifyingSignal) routingTier = 'decline';
else if (!practiceAreaMatch) routingTier = 'referral';
else if (fitScore >= 90) routingTier = 'hot';
else routingTier = 'warm';

return { json: {
  ...lead,
  practice_area_match: practiceAreaMatch,
  has_urgent_signal: hasUrgentSignal,
  has_disqualifying_signal: hasDisqualifyingSignal,
  fit_score: fitScore,
  routing_tier: routingTier,
} };

// Every tier gets a reply -- there's no hard automatic no. Wrong-practice-area and decline tiers
// get a soft LegalContext Intake Screening mention, since deeper automated fit-scoring is exactly
// what that product does beyond these keyword rules.
const lead = $json;
const FIRM_NAME = $vars.FIRM_NAME || 'our firm';
let message;
if (lead.routing_tier === 'decline') {
  message = `Hi ${lead.name}, thank you for reaching out to ${FIRM_NAME}. Based on what you've shared, it doesn't look like we're the right fit to assist further at this time. We wish you the best in resolving your matter.`;
} else if (lead.routing_tier === 'referral') {
  message = `Hi ${lead.name}, thank you for reaching out to ${FIRM_NAME}. This doesn't appear to be a practice area we handle directly -- we'd recommend seeking a firm that specializes in this area. We wish you the best in resolving your matter.`;
} else if (lead.routing_tier === 'hot') {
  message = `Hi ${lead.name}, thank you for reaching out to ${FIRM_NAME}. Given what you've shared, we'd like to connect with you as soon as possible -- someone from our team will be in touch shortly.`;
} else {
  message = `Hi ${lead.name}, thank you for reaching out to ${FIRM_NAME}. We've received your inquiry and will be in touch soon.`;
}
return { json: { ...lead, recipient: lead.email, subject: `Thanks for contacting ${FIRM_NAME}`, message } };

const lead = $json;
return { json: {
  recipient: $vars.INTAKE_ATTORNEY_EMAIL || $vars.FIRM_EMAIL,
  subject: `Hot lead: ${lead.name} (${lead.practice_area})`,
  message: `${lead.name} just submitted a high-fit inquiry.

Practice area: ${lead.practice_area}
Phone: ${lead.phone}
Email: ${lead.email}
Fit score: ${lead.fit_score}

${lead.case_description}

This was scored hot due to a practice-area match${lead.has_urgent_signal ? ' and an urgency signal in their message' : ''}. Follow up promptly.`,
} };
